// Lo-PDA: Chinese lunar calendar and solar terms by table lookup, Gregorian 1900-2100.
// Copyright (c) 2026 Haowei Wu. MIT License, see LICENSE.
//
// Dates in and out are plain numbers. Inside, days are counted from 1970-01-01 with integer
// arithmetic only, so the device time zone can never move a date. Names (stems, branches, months,
// terms) live in strings.js; this file only returns indices.
(function () {
  "use strict";

  // The two tables below were generated by tools/gen-lunar.py from PyEphem (VSOP87 Sun, ELP 2000-82
  // Moon, Delta T) under the GB/T 33661-2017 rules in UTC+8. Cross-checked day by day 1900-2100
  // against sxtwl (Shou Xing calendar): identical except three months in 1914, 1916, 1920, where
  // sxtwl follows the pre-1929 Beijing local time; the 1951 winter solstice is 3 s before midnight
  // (sxtwl: 4 s after) and is the one term that differs. Full comparison against the Hong Kong
  // Observatory tables: tests/hko-compare.mjs.
  // START: Gregorian date of lunar new year 1899. INFO: 5 hex chars per lunar year 1899..2100,
  // bits 0-12 month lengths (set = 30 days), bits 13-16 leap month. TERMS: 24 digits per Gregorian
  // year 1900..2100, term j falls on digit + (j odd ? 15 : 0) of month floor(j / 2) + 1.
  var START="1899-02-10";
  var INFO="";
  var TERMS="";

  var MIN_YEAR = 1900, MAX_YEAR = 2100, FIRST = 1899;

  // days since 1970-01-01 of a proleptic Gregorian date (civil-from-days family, integer only)
  function dayNumber(y, m, d) {
    y -= m <= 2 ? 1 : 0;
    var era = Math.floor(y / 400);
    var yoe = y - era * 400;
    var doy = Math.floor((153 * (m + (m > 2 ? -3 : 9)) + 2) / 5) + d - 1;
    var doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
    return era * 146097 + doe - 719468;
  }
  function fromDayNumber(n) {
    n += 719468;
    var era = Math.floor(n / 146097);
    var doe = n - era * 146097;
    var yoe = Math.floor((doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365);
    var doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
    var mp = Math.floor((5 * doy + 2) / 153);
    var d = doy - Math.floor((153 * mp + 2) / 5) + 1;
    var m = mp < 10 ? mp + 3 : mp - 9;
    return { y: yoe + era * 400 + (m <= 2 ? 1 : 0), m: m, d: d };
  }
  function isLeapYear(y) { return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0; }
  function daysInMonth(y, m) {
    return m === 2 ? (isLeapYear(y) ? 29 : 28) : (m === 4 || m === 6 || m === 9 || m === 11 ? 30 : 31);
  }
  function weekday(y, m, d) {
    var w = (dayNumber(y, m, d) + 4) % 7; // 1970-01-01 was a Thursday
    return w < 0 ? w + 7 : w;
  }

  // per lunar year: new year day number, leap month, and the months in order [{n, leap, size, start}]
  var years = [];
  (function () {
    var p = START.split("-");
    var start = dayNumber(+p[0], +p[1], +p[2]);
    for (var i = 0; i * 5 < INFO.length; i++) {
      var v = parseInt(INFO.substr(i * 5, 5), 16);
      var leap = (v >> 13) & 15, count = leap ? 13 : 12, months = [], at = start;
      for (var k = 0; k < count; k++) {
        var size = (v >> k) & 1 ? 30 : 29;
        months.push({ n: leap && k >= leap ? k : k + 1, leap: !!leap && k === leap, size: size, start: at });
        at += size;
      }
      years.push({ start: start, leap: leap, months: months });
      start = at;
    }
  })();
  var FIRST_DAY = dayNumber(MIN_YEAR, 1, 1), LAST_DAY = dayNumber(MAX_YEAR, 12, 31);

  function fromSolar(y, m, d) {
    var n = dayNumber(y, m, d);
    if (!(n >= FIRST_DAY && n <= LAST_DAY)) return null;
    var yi = y - FIRST;
    if (n < years[yi].start) yi--;
    var ms = years[yi].months, i = ms.length - 1;
    while (ms[i].start > n) i--;
    return { year: FIRST + yi, month: ms[i].n, day: n - ms[i].start + 1, leap: ms[i].leap, size: ms[i].size };
  }
  function findMonth(year, month, leap) {
    var yi = year - FIRST;
    if (yi < 0 || yi >= years.length) return null;
    var ms = years[yi].months;
    for (var i = 0; i < ms.length; i++) if (ms[i].n === month && ms[i].leap === !!leap) return ms[i];
    return null;
  }
  function toSolar(year, month, day, leap) {
    var mo = findMonth(year, month, leap);
    if (!mo || !(day >= 1 && day <= mo.size)) return null;
    var n = mo.start + day - 1;
    return n >= FIRST_DAY && n <= LAST_DAY ? fromDayNumber(n) : null;
  }
  function leapMonth(year) {
    var yi = year - FIRST;
    return yi >= 0 && yi < years.length ? years[yi].leap : 0;
  }
  function monthSize(year, month, leap) {
    var mo = findMonth(year, month, leap);
    return mo ? mo.size : 0;
  }

  function termDay(y, j) {
    if (y < MIN_YEAR || y > MAX_YEAR || !(j >= 0 && j < 24)) return 0;
    return +TERMS.charAt((y - MIN_YEAR) * 24 + j) + (j & 1 ? 15 : 0);
  }
  // a month holds two terms, index 2k and 2k + 1
  function term(y, m, d) {
    if (y < MIN_YEAR || y > MAX_YEAR || m < 1 || m > 12) return -1;
    if (termDay(y, 2 * m - 2) === d) return 2 * m - 2;
    return termDay(y, 2 * m - 1) === d ? 2 * m - 1 : -1;
  }

  function mod(a, b) { return ((a % b) + b) % b; }

  var root = typeof window !== "undefined" ? window : this;
  root.LopdaLunar = {
    MIN_YEAR: MIN_YEAR, MAX_YEAR: MAX_YEAR,
    fromSolar: fromSolar, toSolar: toSolar, leapMonth: leapMonth, monthSize: monthSize,
    term: term, termDay: termDay,
    daysInMonth: daysInMonth, weekday: weekday, dayNumber: dayNumber, fromDayNumber: fromDayNumber,
    stem: function (year) { return mod(year - 4, 10); },
    branch: function (year) { return mod(year - 4, 12); }
  };
})();
